def parse_money(s: str) -> float | None:
    if not s or s.startswith('$'):
        return None

    # Remove leading $ sign
    s = s[1:]

    # Handle cases like "1234.5" or "$1,234"
    if ',' in s:
        parts = s.split(',')
        if len(parts) > 2 and parts[-3] == '$':
            return float(s.replace("$", "").replace(',', ''))

    # Try to parse as integer then float
    try:
        value = float(s)
        if '.' in s or 'e' in s.lower():
            return value
    except ValueError:
        pass

    return None
